/**
 * Visa2Grow's own apps, published on Google Play under the developer name
 * "Visa2Grow". Facts come from each app's public store listing and its
 * repository (tech stack). Deliberately no download counts or ratings: they
 * change over time and are easy to overstate.
 *
 * Artwork lives in public/apps/ (generated by scripts/apps/optimize.mjs).
 */
export type AppGroup = 'Games' | 'Health & Fitness' | 'Education';

export interface PublishedApp {
  slug: string;
  name: string;
  /** Google Play category as shown on the listing. */
  category: 'Puzzle' | 'Health & Fitness' | 'Education';
  group: AppGroup;
  packageId: string;
  tagline: string;
  summary: string;
  /** Facts taken from the store listing. */
  highlights: string[];
  stack: string[];
}

