export const APP_GROUPS: AppGroup[] = ['Games', 'Health & Fitness', 'Education'];

export const playUrl = (app: PublishedApp) => `https://play.google.com/store/apps/details?id=${app.packageId}`;
export const appIcon = (app: PublishedApp) => `/apps/${app.slug}-icon.webp`;
export const appFeature = (app: PublishedApp, width: 640 | 1024) => `/apps/${app.slug}-feature-${width}.webp`;

/** Short display name, e.g. "FiTrack" from "FiTrack — Workout & Diet". */
export const shortName = (app: PublishedApp) => app.name.split(/\s[—–:]\s?|:\s/)[0]!.trim();
